CREATE TABLE bracel_event_clock(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),position bigint NOT NULL,floor bigint NOT NULL); INSERT INTO bracel_event_clock VALUES(true,0,0); CREATE TABLE bracel_events(position bigint PRIMARY KEY,id uuid NOT NULL UNIQUE,scope text NOT NULL,topic text NOT NULL,kind text NOT NULL,version integer NOT NULL,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp()); CREATE INDEX bracel_events_subscription ON bracel_events(scope,topic,position); CREATE TABLE bracel_event_consumers(consumer text NOT NULL,event_id uuid NOT NULL,PRIMARY KEY(consumer,event_id));